{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['Weekday', 'Offday'][datum.__input__]",
      "as": "scenario_name"
    }
  ],
  "facet": {
    "field": "carpark",
    "type": "nominal",
    "title": null
  },
  "columns": 2,
  "spec": {
    "width": 240,
    "height": 130,
    "encoding": {
      "x": {
        "field": "hour",
        "type": "quantitative",
        "title": "Hour",
        "scale": {
          "domain": [
            0,
            23
          ]
        }
      },
      "color": {
        "field": "scenario_name",
        "type": "nominal",
        "title": null,
        "scale": {
          "domain": [
            "Weekday",
            "Offday"
          ],
          "range": [
            "#3b6fd4",
            "#f59e0b"
          ]
        }
      }
    },
    "layer": [
      {
        "mark": {
          "type": "area",
          "opacity": 0.25
        },
        "encoding": {
          "y": {
            "field": "lower",
            "type": "quantitative",
            "title": "Occupancy",
            "scale": {
              "domain": [
                0,
                1.05
              ]
            }
          },
          "y2": {
            "field": "upper"
          }
        }
      },
      {
        "mark": {
          "type": "line",
          "strokeWidth": 2,
          "tooltip": true
        },
        "encoding": {
          "y": {
            "field": "occupancy",
            "type": "quantitative"
          }
        }
      }
    ]
  }
}

{
