{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['M5', 'M6', 'M7'][datum.__input__]",
      "as": "scenario_name"
    },
    {
      "calculate": "max(0, datum.mean - datum.sd)",
      "as": "lower"
    },
    {
      "calculate": "datum.mean + datum.sd",
      "as": "upper"
    }
  ],
  "width": 420,
  "height": 260,
  "encoding": {
    "x": {
      "field": "damage_state",
      "type": "nominal",
      "title": null,
      "sort": [
        "Slight",
        "Moderate",
        "Extensive",
        "Complete"
      ],
      "axis": {
        "labelAngle": 0
      }
    },
    "xOffset": {
      "field": "scenario_name",
      "sort": [
        "M5",
        "M6",
        "M7"
      ]
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "tooltip": true
      },
      "encoding": {
        "y": {
          "field": "mean",
          "type": "quantitative",
          "title": "Proportion of bridges in damage state"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "title": null,
          "scale": {
            "domain": [
              "M5",
              "M6",
              "M7"
            ],
            "range": [
              "#6a4fc4",
              "#9ca3af",
              "#f28c28"
            ]
          }
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "strokeDash": [
          4,
          3
        ],
        "color": "#333333"
      },
      "encoding": {
        "y": {
          "field": "lower",
          "type": "quantitative"
        },
        "y2": {
          "field": "upper"
        }
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#333333",
        "size": 8,
        "thickness": 1.5
      },
      "encoding": {
        "y": {
          "field": "upper",
          "type": "quantitative"
        }
      }
    }
  ]
}

