{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['Baseline', 'Proposal'][datum.__input__]",
      "as": "scenario_name"
    }
  ],
  "width": {
    "step": 120
  },
  "height": 260,
  "encoding": {
    "x": {
      "field": "scenario_name",
      "type": "nominal",
      "title": null,
      "axis": {
        "labelAngle": 0
      },
      "sort": [
        "Baseline",
        "Proposal"
      ]
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "tooltip": true
      },
      "encoding": {
        "y": {
          "field": "gwp",
          "type": "quantitative",
          "title": "GWP (kg CO2e/m2/year)"
        },
        "color": {
          "field": "stage",
          "type": "nominal",
          "title": "Lifecycle stage",
          "scale": {
            "domain": [
              "A1-A3",
              "A4",
              "A5",
              "B4",
              "B6",
