      "encoding": {
        "y": {
          "field": "gwp",
          "aggregate": "sum",
          "type": "quantitative"
        },
        "text": {
          "field": "gwp",
          "aggregate": "sum",
          "type": "quantitative",
          "format": ".1f"
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['Solution 1', 'Solution 2'][datum.__input__]",
      "as": "scenario_name"
    },
    {
      "calculate": "['#d9654b', '#4a72b0'][datum.__input__]",
      "as": "scenario_color"
    }
  ],
  "facet": {
    "field": "scenario_name",
    "type": "nominal",
    "title": null,
    "header": {
      "labelFontSize": 13,
      "labelFontWeight": "bold"
    },
    "sort": [
      "Solution 1",
      "Solution 2"
    ]
  },
  "spec": {
    "width": 170,
    "height": 170,
    "transform": [
      {
        "calculate": "datum.component === 'Structural' ? datum.scenario_color : '#c4c4c4'",
        "as": "slice_color"
      },
      {
        "calculate": "format(datum.share, '.1f') + '%'",
        "as": "label"
      }
    ],
    "encoding": {
      "theta": {
        "field": "share",
        "type": "quantitative",
        "stack": true
      },
      "order": {
        "field": "component",
        "sort": "descending"
      }
    },
    "layer": [
      {
        "mark": {
          "type": "arc",
          "innerRadius": 40,
          "tooltip": true
        },
        "encoding": {
          "color": {
            "field": "slice_color",
            "type": "nominal",
            "scale": null
          }
        }
      },
      {
        "mark": {
          "type": "text",
          "radius": 62,
          "color": "white",
          "fontWeight": "bold"
        },
        "encoding": {
          "text": {
            "field": "label"
          }
        }
      }
    ]
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['Route 1', 'Route 2', 'Route 3'][datum.__input__]",
      "as": "scenario_name"
    }
  ],
  "width": {
    "step": 115
  },
  "height": {
    "step": 70
  },
  "encoding": {
    "x": {
      "field": "criterion",
      "type": "nominal",
      "sort": [
        "Departure Time",
        "Travel Cost",
        "Road Importance",
        "Intersection Number",
        "Travel Distance",
        "Congestion Degree"
      ],
      "title": null,
      "axis": {
        "orient": "top",
        "labelAngle": 0,
        "labelLimit": 0
      }
    },
    "y": {
      "field": "scenario_name",
      "type": "nominal",
      "title": null,
      "sort": [
        "Route 1",
        "Route 2",
        "Route 3"
      ]
    }
  },
  "layer": [
    {
      "transform": [
        {
          "filter": "datum.criterion === 'Departure Time'"
        }
      ],
      "mark": {
        "type": "square",
        "size": 160,
        "xOffset": -44,
        "opacity": 1
      },
      "encoding": {
        "fill": {
          "field": "scenario_name",
          "type": "nominal",
          "legend": null,
          "scale": {
            "domain": [
              "Route 1",
              "Route 2",
              "Route 3"
            ],
            "range": [
              "#5b8db8",
              "#8e6bbf",
              "#c9a227"
            ]
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.effect !== 0"
        },
        {
          "calculate": "abs(datum.effect)",
          "as": "strength"
        },
        {
          "calculate": "datum.effect > 0 ? 'positive' : 'negative'",
          "as": "sign"
        }
      ],
      "mark": {
        "type": "point",
        "filled": false,
        "strokeWidth": 3,
        "tooltip": true
      },
      "encoding": {
        "size": {
          "field": "strength",
          "type": "quantitative",
          "title": "Effect",
          "scale": {
            "domain": [
              0,
              1
            ],
            "range": [
              0,
              1800
            ]
          }
        },
        "stroke": {
          "field": "sign",
          "type": "nominal",
          "title": null,
          "scale": {
            "domain": [
              "positive",
              "negative"
            ],
            "range": [
              "#e4572e",
              "#17605c"
            ]
          }
        }
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "transform": [
    {
      "calculate": "['Passive Green Wall', 'Active Modular System', 'Intensive Planting'][datum.__input__]",
      "as": "scenario_name"
    },
    {
      "calculate": "datum.__input__",
      "as": "scenario_order"
    },
    {
      "calculate": "datum.scenario_name",
      "as": "Scenario"
    },
    {
      "calculate": "format(datum.u_value, '.2f')",
      "as": "New U-value (W/m2K)"
    },
    {
      "calculate": "format(datum.energy_savings, ',')",
      "as": "Energy savings (kWh/year)"
    },
    {
      "calculate": "format(datum.co2_reduction, ',')",
      "as": "CO2 reduction (kg/year)"
    },
    {
      "fold": [
        "Scenario",
        "New U-value (W/m2K)",
        "Energy savings (kWh/year)",
        "CO2 reduction (kg/year)"
      ],
      "as": [
        "column",
        "cell"
      ]
    }
  ],
  "width": {
    "step": 190
  },
  "height": {
    "step": 38
  },
  "encoding": {
    "x": {
      "field": "column",
      "type": "nominal",
      "sort": [
        "Scenario",
        "New U-value (W/m2K)",
        "Energy savings (kWh/year)",
        "CO2 reduction (kg/year)"
      ],
      "title": null,
      "axis": {
        "orient": "top",
        "labelAngle": 0,
        "labelFontSize": 12,
        "labelFontWeight": "bold",
        "labelColor": "#333333",
        "labelPadding": 8,
        "labelLimit": 0,
        "domain": false,
        "ticks": false
      }
    },
    "y": {
      "field": "scenario_name",
      "type": "nominal",
      "sort": {
        "field": "scenario_order"
      },
      "axis": null
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#d6d9de",
        "strokeWidth": 1
      },
      "encoding": {
        "fill": {
          "condition": {
            "test": "datum.scenario_order % 2 === 1",
            "value": "#f5f6f8"
          },
          "value": "#ffffff"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.column === 'Scenario'"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 13,
        "fontWeight": "bold",
        "tooltip": true
      },
      "encoding": {
        "text": {
          "field": "cell",
          "type": "nominal"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "legend": null,
          "scale": {
            "domain": [
              "Passive Green Wall",
              "Active Modular System",
              "Intensive Planting"
            ],
            "range": [
              "#6aa84f",
              "#38812f",
              "#1b5e20"
            ]
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.column !== 'Scenario'"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 13,
        "tooltip": true
      },
      "encoding": {
        "text": {
          "field": "cell",
          "type": "nominal"
        },
        "color": {
          "field": "scenario_name",
          "type": "nominal",
          "legend": null,
          "scale": {
            "domain": [
              "Passive Green Wall",
              "Active Modular System",
              "Intensive Planting"
            ],
            "range": [
              "#6aa84f",
              "#38812f",
              "#1b5e20"
            ]
          }
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    }
  }
}
